export const weatherViews={
 'weather-cells':[['hadley','Hadley process'],['three','Three-cell section'],['winds','Prevailing winds'],['hemispheres','Both hemispheres']],
 'weather-heat':[['balance','Energy imbalance'],['air','Air & latent energy'],['ocean','Ocean transport'],['coupled','Air–ocean exchange']],
 'weather-past':[['intervals','Glacial / interglacial'],['ice','Ice & sea level'],['scale','Compare time scales'],['holocene','Quaternary context']],
 'weather-causes':[['orbit','Orbital shape'],['tilt','Axial tilt'],['precession','Precession'],['solar','Solar variation'],['volcano','Volcanic aerosols'],['compare','Compare mechanisms']],
 'weather-evidence':[['icecore','Ice-core components'],['rings','Tree rings'],['pollen','Pollen records'],['history','Historical sources'],['corroborate','Compare evidence']]
};
export const weatherRequirements=Object.fromEntries(Object.entries(weatherViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const weatherAnimated=(k,v)=>k==='weather-cells'?['hadley','three'].includes(v):k==='weather-heat'?v!=='balance':k==='weather-past'?v==='ice':k==='weather-causes'?v!=='compare':false;
export const cellBands=[{name:'Hadley',from:0,to:30,surface:'equatorward'},{name:'Ferrel',from:30,to:60,surface:'poleward'},{name:'Polar',from:60,to:90,surface:'equatorward'}];
export const pressureBands=[{latitude:0,motion:'rising',pressure:'low'},{latitude:30,motion:'sinking',pressure:'high'},{latitude:60,motion:'rising',pressure:'low'},{latitude:90,motion:'sinking',pressure:'high'}];
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const ln=(p,c='#b7dce5',w=3,rest='')=>`<path d="${p}" stroke="${c}" stroke-width="${w}" fill="none" ${rest}/>`;
const ar=(x,y,a,b,c='#eea18b')=>ln(`M${x} ${y}L${a} ${b}`,c,3,'marker-end="url(#wArrow)"');
const dot=(x,y,r=5,c='#edc69d')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,h,s)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#365168" stroke="#a3bdc6"/>`+tx(x+9,y+24,s,12);
const wrap=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><marker id="wArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#eea18b"/></marker><linearGradient id="wEarth" x2="1" y2="1"><stop stop-color="#b4d7d8"/><stop offset="1" stop-color="#5b8da5"/></linearGradient></defs><g font-family="sans-serif" fill="#edf1ef">${b}</g></svg><p class="geo-caption">${c}</p>`;
const onPath=(points,t)=>{const n=points.length-1,p=Math.min(.999999,Math.max(0,t))*n,i=Math.floor(p),f=p-i;return [points[i][0]+(points[i+1][0]-points[i][0])*f,points[i][1]+(points[i+1][1]-points[i][1])*f];};
const cycle=(points,t,color)=>{const [x,y]=onPath(points,t);return ln(points.map(([x,y],i)=>(i?'L':'M')+x+' '+y).join(' '),color,3)+dot(x,y,6,color);};
export function weatherScene(k,selected,t=0){const options=weatherViews[k];if(!options)return '';const v=options.some(x=>x[0]===selected)?selected:options[0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!weatherAnimated(k,v))t=0;let b='',c='';
 if(k==='weather-cells'){
  if(v==='hemispheres'){b=tx(25,30,'SIX CELLS · simplified zonal-mean layout');const labels=['Polar','Ferrel','Hadley','Hadley','Ferrel','Polar'];labels.forEach((s,i)=>b+=box(30+i*64,110,59,60,s));b+=tx(24,205,'90°S')+tx(88,205,'60°S')+tx(152,205,'30°S')+tx(216,205,'0°')+tx(277,205,'30°N')+tx(341,205,'60°N')+tx(393,205,'90°N',11)+tx(25,280,'Three cells per hemisphere · boundaries vary',13);c='Hadley, Ferrel and Polar cells occur in both hemispheres in this simplified average framework. Equal-sized boxes do not represent atmospheric volumes or fixed daily boundaries.';}
  else if(v==='winds'){b=tx(25,30,'PREVAILING SURFACE WINDS · broad directions')+tx(25,75,'Northern Hemisphere',16)+tx(25,110,'Trades: NE → SW')+tx(25,140,'Westerlies: SW → NE')+tx(25,170,'Polar easterlies: NE → SW')+tx(25,215,'Southern Hemisphere',16)+tx(25,250,'Trades: SE → NW')+tx(25,280,'Westerlies: NW → SE')+tx(25,310,'Polar easterlies: SE → NW');c='Wind names describe where air comes from. Coriolis deflects movement right in the Northern Hemisphere and left in the Southern. These are broad idealised belts, not local wind forecasts.';}
  else{const only=v==='hadley',xs=only?[75,365]:[50,165,280,395];b=tx(25,30,only?'HADLEY · equator to subtropics':'ONE HEMISPHERE · equator to pole')+ln(`M${xs[0]} 265H${xs.at(-1)}`,'#c9d5d5',2);const count=only?1:3;for(let i=0;i<count;i++){const a=xs[i],z=xs[i+1],mid=(a+z)/2,reverse=i===1;const p=reverse?[[a,250],[z,250],[z,100],[a,100],[a,250]]:[[a,250],[a,100],[z,100],[z,250],[a,250]];b+=cycle(p,t,['#efb49e','#b7dbe5','#d6d5b1'][i])+tx(mid-25,80,cellBands[i].name,13)+ar(reverse?a+20:z-20,250,reverse?z-20:a+20,250)+ar(reverse?z-20:a+20,100,reverse?a+20:z-20,100);}const bands=only?[pressureBands[0],pressureBands[1]]:pressureBands;bands.forEach((p,i)=>{b+=p.motion==='rising'?ar(xs[i],205,xs[i],150):ar(xs[i],150,xs[i],205);b+=tx(xs[i]-15,290,p.latitude+'°',12)+tx(xs[i]-16,312,p.pressure.toUpperCase(),11);});b+=tx(25,340,only?'Rise / cool / upper flow / sink / surface return':'Rise0° · sink30° · rise60° · sink90°',12);c=only?'Near the equator, surface convergence and ascent connect with upper-level poleward flow, subtropical descent and surface return. The particle follows an idealised Hadley circuit; actual air does not stay in a permanent rectangular tube.':'Idealised zonal-mean cells: Hadley0–30°, Ferrel30–60°, Polar60–90°. Surface flow differs between cells; rising/sinking belts alternate. Ferrel circulation involves travelling weather systems, not simply direct tropical-style convection. Geometry and timing are symbolic.';}
 }
 if(k==='weather-heat'){
  if(v==='balance'){b=tx(25,30,'LONG-TERM ENERGY IMBALANCE')+box(25,80,185,80,'Low latitudes: surplus')+box(230,80,185,80,'High latitudes: deficit')+ar(85,210,355,210)+tx(90,248,'Net energy transfer poleward',14)+tx(25,310,'Surplus: received > lost · deficit: received < lost',12);c='On average, lower latitudes receive more energy than they lose and higher latitudes the reverse. Net atmospheric and oceanic transport redistributes energy; this is not a measured radiation budget.';}
  else if(v==='air'){b=tx(25,30,'AIR AND WATER VAPOUR TRANSPORT ENERGY')+box(25,225,150,45,'Warm ocean surface')+box(245,80,165,50,'Cooler air / cloud')+ar(95,215,95,120)+ar(105,115,245,115)+dot(90+t*175,170-t*50,7)+tx(25,75,'Evaporation: energy taken up',12)+tx(180,185,'Condensation: energy released',12)+tx(25,315,'Air movement + latent energy · not one fixed parcel route',12);c='Evaporation takes up energy; water vapour can be transported and condensation releases latent energy to surrounding air. Air motion also transfers sensible heat. The combined system has net poleward transfer; individual pathways vary.';}
  else if(v==='ocean'){b=tx(25,30,'OCEAN HEAT TRANSPORT · conceptual section')+'<rect x="25" y="130" width="390" height="150" rx="12" fill="#598aa0"/>'+ar(55,165,370,165)+ar(370,245,55,245)+dot(55+t*315,165,7,'#f0b399')+dot(370-t*315,245,7,'#b8dce8')+tx(25,95,'Lower latitudes',13)+tx(275,95,'Higher latitudes',13)+tx(55,205,'Warm transport / cooler return',14)+tx(25,320,'Schematic pathways · not a map of one real current',12);c='Warm ocean flows can move energy away from the tropics and exchange heat with air. Returning cooler flows and mixing form a complex circulation driven by wind, rotation and density effects. This is not a literal two-pipe ocean or a measured current map.';}
  else{b=tx(25,30,'COUPLED OCEAN–ATMOSPHERE')+'<rect x="25" y="200" width="390" height="90" rx="12" fill="#6495aa"/>'+tx(35,175,'Atmosphere',16)+tx(35,255,'Ocean',16)+ar(120,210,120,100)+ar(300,100,300,210)+dot(120,210-t*105,7)+dot(300,105+t*105,7,'#b8dce8')+tx(25,75,'Heat / moisture exchange and wind-driven motion',12)+tx(25,325,'Systems interact · local climate has several controls',12);c='The ocean exchanges heat and moisture with air, while winds help drive surface water movement. Atmospheric and oceanic influences interact with latitude, land and seasons; one current does not explain every UK weather event.';}
 }
 if(k==='weather-past'){
  if(v==='intervals'){b=tx(25,30,'CONCEPTUAL ORDER · NOT MEASURED DURATIONS')+box(25,100,120,70,'Glacial')+box(160,100,120,70,'Interglacial')+box(295,100,120,70,'Glacial')+ar(70,220,370,220)+tx(25,270,'Colder / more ice ↔ warmer / less extensive ice',13)+tx(25,310,'Real intervals vary in length, timing and extent',13);c='The Quaternary contains repeated glacial and interglacial intervals. Equal boxes show a comparison only, not equal durations, a measured temperature series or the full actual chronology.';}
  else if(v==='scale'){b=tx(25,30,'CHOOSE A TIME SCALE FOR THE CLAIM')+box(25,75,390,50,'A cold day: short-term weather')+box(25,150,390,50,'Winter / summer: seasonal variation')+box(25,225,390,60,'Glacial / interglacial: long-term climate')+tx(25,325,'One event does not establish the whole long-term trend',12);c='Weather events, seasonal changes and long climatic intervals answer different questions. This framework has no measured values and cannot date the beginning of a new glaciation.';}
  else if(v==='holocene'){b=tx(25,30,'QUATERNARY · roughly last2.6million years')+box(25,85,390,70,'Repeated glacials and interglacials')+box(25,195,390,70,'Holocene: current interglacial')+tx(40,295,'Began about11,700years ago',15)+tx(25,330,'Boxes are not proportional to geological time',12);c='The Quaternary includes the Pleistocene and Holocene. The current Holocene began about11,700years ago. This context does not predict future ice growth or explain recent warming by orbital cycles alone.';}
  else{const extent=90+t*140,sea=235+t*35;b=tx(25,30,'MORE LAND ICE → MORE STORED WATER')+'<path d="M20 285H200V315H20Z" fill="#929f94"/>'+`<path d="M35 ${245-t*100}H185V285H35Z" fill="#c9e3eb"/><path d="M245 ${sea}H420V315H245Z" fill="#76a9bd"/>`+tx(25,75,'Land-ice store grows (symbolic)',13)+tx(255,225,'Sea level lower',12)+ar(365,235,365,275)+tx(25,340,'Land-ice store and ocean volume · not scale or a forecast',12);c='More water stored in land ice contributes to lower global sea level; ice loss can return water to oceans. Extent, time and sea-level change are exaggerated. This is a conceptual store comparison, not measured Quaternary data.';}
 }
 if(k==='weather-causes'){
  if(v==='compare'){b=tx(25,30,'MATCH MECHANISM, PATTERN AND TIME SCALE')+box(25,75,390,45,'Orbital: sunlight distribution / long periods')+box(25,140,390,45,'Solar: changing energy output')+box(25,205,390,45,'Volcanic: reflective aerosols / limited duration')+tx(25,310,'Natural history ≠ attribution of rapid recent warming',12);c='Orbital, solar and volcanic influences have different mechanisms and time scales. Their existence does not by itself explain rapid recent warming; evidence supports a separate human greenhouse-gas influence.';}
  else if(v==='orbit'){const a=135,baxis=110-t*25,focus=Math.sqrt(a*a-baxis*baxis),ang=t*2*Math.PI;b=tx(25,30,'ORBITAL SHAPE · geometry/time exaggerated')+`<ellipse cx="230" cy="185" rx="${a}" ry="${baxis}" fill="none" stroke="#9dbcc6" stroke-width="2"/>`+dot(230-focus,185,20,'#e6c393')+dot(230+a*Math.cos(ang),185+baxis*Math.sin(ang),12,'#a4d1df')+tx(25,325,'Changes seasonal / geographical sunlight distribution',12);c='Changes in orbital shape are one Milankovitch component. This exaggerated schematic compresses long changes and orbital travel; it does not imply that current rapid warming comes from Earth suddenly moving much closer to the Sun.';}
  else if(v==='tilt'||v==='precession'){const tilt=v==='tilt'?20+t*20:23,x=v==='tilt'?Math.sin(tilt*Math.PI/180)*85:Math.sin(t*2*Math.PI)*35,y=v==='tilt'?Math.cos(tilt*Math.PI/180)*85:80+10*Math.cos(t*2*Math.PI);b=tx(25,30,v==='tilt'?'AXIAL TILT · angular change exaggerated':'PRECESSION · changing axis orientation')+dot(220,195,65,'#85b4c5')+ln(`M${220-x} ${195+y}L${220+x} ${195-y}`,'#edc69f',4)+ln('M220 90V300','#8faeb9',1,'stroke-dasharray="5 5"');if(v==='precession')b+='<ellipse cx="220" cy="115" rx="35" ry="10" fill="none" stroke="#c9d9dc"/>';b+=tx(25,325,v==='tilt'?'Tilt magnitude varies over long periods':'Axis orientation changes · not daily spin',12);c=v==='tilt'?'Changes in axial tilt alter seasonal and geographical sunlight distribution. The angle and time scale are exaggerated for visibility; this is not Earth’s actual tilt range or a present-day trend.':'Precession changes the orientation of Earth’s axis over long periods. The wobble is shown schematically and is distinct from daily rotation or a changing tilt magnitude.';}
  else if(v==='solar'){const pulse=.5-.5*Math.cos(t*2*Math.PI);b=tx(25,30,'SOLAR VARIATION · output change exaggerated')+dot(95,185,40+6*pulse,'#ebc995')+dot(345,185,42,'#85b4c5');for(let i=0;i<4;i++)b+=ln(`M150 ${135+i*33}H285`,'#ebc995',2+pulse*3);b+=tx(25,305,'Energy output varies · not an explanation of all warming',12);c='Variation in solar output can influence energy reaching Earth. The pulse is deliberately exaggerated and is not measured irradiance, a forecast or an explanation of all recent warming.';}
  else{b=tx(25,30,'LARGE ERUPTION → REFLECTIVE AEROSOLS')+'<path d="M20 310L105 190 140 215 165 190 260 310Z" fill="#8b9d92"/>'+ln('M50 105H410','#a6bdc5',2,'stroke-dasharray="6 5"');for(let i=0;i<12;i++)b+=dot(150+(i*19+t*120)%245,90+i%3*14,3,'#d0d9d4');b+=ar(90,45,230,100)+ar(230,100,365,40)+tx(25,155,'Sulfate aerosol layer: schematic',13)+tx(25,335,'Some sunlight reflected · possible temporary cooling',12);c='Some large explosive eruptions form reflective sulfate aerosols high in the atmosphere, reducing sunlight reaching the surface for a limited time. Ash alone is not the full mechanism; eruption magnitude, altitude and persistence matter.';}
 }
 if(k==='weather-evidence'){
  if(v==='icecore'){b=tx(25,30,'ICE CORE · different components, different clues')+'<rect x="70" y="75" width="95" height="235" rx="18" fill="#a6cbd8"/>';for(let i=0;i<7;i++)b+=ln(`M72 ${98+i*28}H163`,'#edf1eb',2)+dot(95+i%3*20,115+i*25,4,'#ecede5');b+=ar(230,110,145,125)+tx(240,105,'Bubble gases:',12)+tx(240,125,'past air composition',12)+ar(230,220,150,230)+tx(240,215,'Ice properties:',12)+tx(240,235,'temperature proxies',12);c='Illustrative layered core, not real sample data. Trapped gas informs past air composition; isotopic properties of ice can help infer temperature with calibration. Ice and enclosed gases may differ in age; dating and uncertainty matter.';}
  if(v==='rings'){b=tx(25,30,'TREE RINGS · growth is not a direct thermometer');for(const r of [95,83,77,62,47,39,21])b+=`<circle cx="150" cy="195" r="${r}" fill="none" stroke="#e0c3a0" stroke-width="4"/>`;b+=tx(265,140,'Temperature',13)+tx(265,175,'Moisture',13)+tx(265,210,'Age / species',13)+tx(265,245,'Disturbance',13)+tx(25,325,'Schematic widths · no measured years or temperatures',12);c='Tree-ring width or density records growth that can respond to several controls. Date and calibrate the record before inferring climate; a wide ring is not universally a hot year. This drawing is not a measured chronology.';}
  if(v==='pollen'){b=tx(25,30,'DATED SEDIMENT · plant-community evidence')+'<rect x="30" y="90" width="150" height="210" rx="8" fill="#9d9b85"/>';for(let i=0;i<4;i++){b+=ln(`M30 ${135+i*45}H180`,'#c8c7af',2);for(let j=0;j<4;j++)b+=dot(55+j*30,112+i*45,j%2?3:5,i%2?'#d6c7a0':'#b8d0b5');}b+=tx(215,130,'Pollen assemblages',13)+tx(215,175,'→ past vegetation',13)+tx(215,220,'→ climate with context',13)+tx(25,330,'Illustrated particles · not observed pollen counts',12);c='Fossil pollen in dated sediment can indicate past vegetation and associated climate conditions. Ecological context, dating and sampling matter; these particles are illustrative, not actual counts or a direct temperature record.';}
  if(v==='history'){b=tx(25,30,'HISTORICAL SOURCES · question the record')+box(25,90,185,60,'Diaries / harvests')+box(230,90,185,60,'Paintings / reports')+tx(25,200,'When and where? Who created it, and why?',14)+tx(25,245,'Coverage, bias, uncertainty and corroboration',13)+tx(25,310,'One event ≠ a regional long-term climate trend',12);c='Historical documents and images can offer dated clues but have uneven coverage and purposes. No authentic historical item is reproduced here; one snowy image alone cannot establish a whole region’s long-term climate.';}
  if(v==='corroborate'){b=tx(25,30,'COMPARE INDEPENDENT EVIDENCE')+box(25,85,185,55,'Ice: gases / proxies')+box(230,85,185,55,'Trees: growth')+box(25,175,185,55,'Pollen: vegetation')+box(230,175,185,55,'History: documents')+tx(25,290,'Compare dates, locations and uncertainties',14)+tx(25,325,'Agreement can strengthen inference · correlation ≠ cause',12);c='Independent records can strengthen a reconstruction when dates, locations and uncertainties are compatible. Agreement does not alone establish the cause of a climate change; no fabricated proxy measurements are used.';}
 }
 return wrap(b,c);
}
